(function(){
  var W = (typeof window!=='undefined') ? window : {};
  var C  = W.__TPL_CONFIG__ || {}, BASE = C.tplSchema || {};
  function clone(o){ return JSON.parse(JSON.stringify(o)); }
  function patch(b,p){
    if(!p || typeof p!=='object') return b;
    Object.keys(p).forEach(function(k){
      var v=p[k];
      if(v && typeof v==='object' && !Array.isArray(v) &&
         b[k] && typeof b[k]==='object' && !Array.isArray(b[k])) patch(b[k],v);
      else b[k] = Array.isArray(v) ? clone(v) : (v && typeof v==='object' ? clone(v) : v);
    });
    return b;
  }
  function mk(p){ return patch(clone(BASE),p); }
  W.__TPL_SETS__ = {
    product: {key:'product', label:'产品档案', desc:'药品与饮片档案 · 默认基线（原 tplSchema 逐字未动）',
              id:BASE.id||'drugArchive', schema:BASE, builtin:true, patch:null},
  };
  Object.keys(W.__TPL_SETS__).forEach(function(k){
    var s=W.__TPL_SETS__[k];
    if(!s.schema && s.patch) s.schema=mk(s.patch);
  });
  
  var KEY='TPL_ACTIVE_SET_V1', k=null;
  try{ var mm=(W.location&&W.location.search||'').match(/[?&]set=([^&]+)/); if(mm)k=decodeURIComponent(mm[1]); }catch(e){}
  try{ if(!k && W.localStorage) k=W.localStorage.getItem(KEY); }catch(e){}
  try{ if(!k && W.name){ var nm=String(W.name).match(/^TPL_SET:([A-Za-z0-9_-]+)$/); if(nm)k=nm[1]; } }catch(e){}
  if(!k || !W.__TPL_SETS__[k]) k='product';
  W.__TPL_ACTIVE_SET__=k;
  if(k!=='product'){
    var s=W.__TPL_SETS__[k];
    if(s && s.schema && C) C.tplSchema=s.schema;
  }
  W.__WL_SETS__=function(){
    return {active:k, keys:Object.keys(W.__TPL_SETS__),
      sets:Object.keys(W.__TPL_SETS__).map(function(x){
        var s=W.__TPL_SETS__[x];
        return {key:x,label:s.label,desc:s.desc,id:s.id,
          cols:((s.schema||{}).list||{}).columns?((s.schema||{}).list||{}).columns.length:0,
          groups:((s.schema||{}).detail||{}).groups?((s.schema||{}).detail||{}).groups.length:0};
      })};
  };
})();
